-- PostgreSQL schema. IDs are immutable text keys matching the project nomenclature.
CREATE TABLE roles(role_id text PRIMARY KEY, role_name text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE requesters(requester_id text PRIMARY KEY, display_name text NOT NULL, role_id text NOT NULL REFERENCES roles(role_id), email text NOT NULL UNIQUE, department text NOT NULL, active boolean NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE terms(term_id text PRIMARY KEY, term_name text NOT NULL UNIQUE, start_date date NOT NULL, end_date date NOT NULL, is_current boolean NOT NULL, CHECK(end_date >= start_date));
CREATE TABLE policy_documents(policy_id text PRIMARY KEY, domain text NOT NULL, title text NOT NULL, version text NOT NULL, effective_from date NOT NULL, effective_to date NOT NULL, status text NOT NULL, source_url text NOT NULL, license text NOT NULL, retrieved_at date NOT NULL, CHECK(effective_to >= effective_from));
CREATE TABLE knowledge_articles(article_id text PRIMARY KEY, domain text NOT NULL, title text NOT NULL, version text NOT NULL, effective_from date NOT NULL, effective_to date NOT NULL, status text NOT NULL, policy_id text NOT NULL REFERENCES policy_documents(policy_id), body text NOT NULL, updated_at timestamptz NOT NULL, CHECK(effective_to >= effective_from), UNIQUE(article_id,version));
CREATE TABLE categories(category_id text PRIMARY KEY, category_code text NOT NULL UNIQUE, display_name text NOT NULL, default_team text NOT NULL, active boolean NOT NULL);
CREATE TABLE tickets(ticket_id text PRIMARY KEY, requester_id text NOT NULL REFERENCES requesters(requester_id), term_id text NOT NULL REFERENCES terms(term_id), category_id text NOT NULL REFERENCES categories(category_id), subject text NOT NULL, description text NOT NULL, priority text NOT NULL CHECK(priority IN ('low','normal','high','urgent')), status text NOT NULL CHECK(status IN ('open','in_progress','pending_requester','resolved','closed','escalated')), created_at timestamptz NOT NULL, due_at timestamptz NOT NULL, ambiguous_flag boolean NOT NULL, urgent_deadline_flag boolean NOT NULL, closed_at timestamptz, issue_type text NOT NULL DEFAULT 'none', CHECK(due_at >= created_at));
CREATE TABLE messages(message_id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES tickets(ticket_id), sequence_no integer NOT NULL CHECK(sequence_no > 0), sender_id text NOT NULL, sender_type text NOT NULL CHECK(sender_type IN ('requester','support_staff')), sent_at timestamptz NOT NULL, body text NOT NULL, is_response boolean NOT NULL, response_supported boolean, UNIQUE(ticket_id,sequence_no));
CREATE TABLE assignments(assignment_id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES tickets(ticket_id), team_name text NOT NULL, assigned_at timestamptz NOT NULL, assigned_by text NOT NULL, is_authorized boolean NOT NULL, ended_at timestamptz, assignment_reason text NOT NULL);
CREATE TABLE slas(sla_id text PRIMARY KEY, ticket_id text NOT NULL UNIQUE REFERENCES tickets(ticket_id), policy_name text NOT NULL, target_business_hours integer NOT NULL CHECK(target_business_hours > 0), started_at timestamptz NOT NULL, deadline_at timestamptz NOT NULL, paused_business_hours numeric NOT NULL DEFAULT 0, breached boolean NOT NULL, clock_type text NOT NULL CHECK(clock_type IN ('business_hours','elapsed_hours')));
CREATE TABLE resolution_feedback(feedback_id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES tickets(ticket_id), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL, submitted_at timestamptz NOT NULL);
CREATE TABLE ticket_article_citations(ticket_id text NOT NULL REFERENCES tickets(ticket_id), article_id text NOT NULL REFERENCES knowledge_articles(article_id), article_version text NOT NULL, message_id text NOT NULL REFERENCES messages(message_id), citation_role text NOT NULL, is_current_at_response boolean NOT NULL, PRIMARY KEY(ticket_id,article_id,message_id));
CREATE TABLE ticket_events(event_id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES tickets(ticket_id), event_type text NOT NULL, from_state text, to_state text, event_at timestamptz NOT NULL, actor text NOT NULL, details text NOT NULL);
-- Ground truth is an evaluation-only table/file. Never join it into model input features.
